        dp[i][i] = 1

    # Fill the DP table
    for length in range(2, n + 1):
        for start in range(n - length + 1):
            end = start + length - 1

            # If characters at the start and end indices match, add 2 to the length of the substring
            if s[start] == s[end]:
                dp[start][end] = dp[start + 1][end - 1] + 2
            else:
                # Otherwise, take the maximum of the two substrings without the characters at the start and end indices
                dp[start][end] = max(dp[start + 1][end], dp[start][end - 1])

    # The length of the longest palindromic subsequence is stored in dp[0][n-1]
    return dp[0][n-1]

